def g(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return default
    return cur

def txt(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([txt(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([txt(k) + ' ' + txt(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def hasinv(inv, target):
    s = txt(inv)
    return bool(target and target in s and 'nothing' not in s and 'not carrying' not in s)

def hook(ctx, nb):
    target = txt(g(ctx, 'task.target_type', ''))
    dest = txt(g(ctx, 'task.destination_type', ''))
    tt = txt(g(ctx, 'task.task_type', ''))
    if not target:
        return None
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = txt(g(ctx, 'action.final_action', g(ctx, 'action.normalized', g(ctx, 'action.raw', ''))))
    obs = txt(ctx.get('observation', ''))
    inv = g(ctx, 'world.inventory', '')
    if verb and target in act and act.startswith(verb + ' '):
        nb['transformed'] = True
    if verb and target in obs and (act.startswith(verb + ' ') or ('you ' + verb) in obs or 'now ' + verb in obs):
        nb['transformed'] = True
    pc = g(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    try:
        old = int(nb.get('placed_count', 0))
    except Exception:
        old = 0
    if pc > old:
        nb['placed_count'] = pc
    adm = [txt(a) for a in (ctx.get('admissible') or [])]
    take_here = bool(target and any(a.startswith('take ' + target + ' ') for a in adm))
    trans_ready = bool(verb and target and any(a.startswith(verb + ' ') and target in a for a in adm))
    put_ready = bool(target and any(a.startswith('put ') and target in a and (not dest or dest in a) for a in adm))
    carrying = hasinv(inv, target)
    wrong = bool(inv and isinstance(inv, (list, tuple, set)) and target not in txt(inv) and 'nothing' not in txt(inv) and 'not carrying' not in txt(inv))
    if wrong or (isinstance(inv, str) and inv and 'nothing' not in inv and 'not carrying' not in inv and target not in inv):
        stage = 'wrong_inventory'
    elif 'two' in tt and nb.get('placed_count', 0) >= 2:
        stage = 'done'
    elif carrying:
        if verb and not nb.get('transformed'):
            stage = 'transform'
        elif put_ready or (dest and any(a.startswith('put ') and dest in a for a in adm)):
            stage = 'put_target'
        else:
            stage = 'go_destination'
    elif take_here or g(ctx, 'world.target_found', False) or g(ctx, 'world.target_location', ''):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['need_verb'] = verb
    nb['take_available'] = take_here
    nb['transform_ready'] = trans_ready
    nb['put_available'] = put_ready
    nb['carrying_target'] = carrying
    return None

def g(ctx, path, default=None):
