def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    if 'slice' in tt:
        return 'slice'
    return ''

def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or txt(g(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or txt(g(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type') or txt(g(ctx, 'task.task_type', ''))
    verb = nb.get('need_verb') or needverb(tt)
    msg = ''
    if not target:
        return None
    if stage == 'wrong_inventory':
        msg = 'You appear to be carrying a non-target item. Do not place it as the goal object; search for or take the requested target type instead.'
    elif stage == 'take_target' and nb.get('take_available') and not nb.get('take_hinted'):
        msg = 'The requested target type is available here; take it before continuing to search other containers.'
    elif stage == 'transform' and verb:
        if nb.get('transform_ready') and not nb.get('transform_hinted'):
            msg = 'The required ' + verb + ' action for the target is available now; use it before placing the item.'
        elif 'two' in tt:
            msg = 'Use the required ' + verb + ' action on this target before placing it, then leave already placed targets at the destination.'
        else:
            place = ''
            if verb == 'clean':
                place = 'sinkbasin'
            if verb == 'heat':
                place = 'microwave'
            if verb == 'cool':
                place = 'fridge'
            if verb == 'slice':
                place = 'knife'
            msg = 'Carry the target to the ' + place + ' and use the ' + verb + ' action before going to the destination.'
    elif stage == 'put_target' and nb.get('put_available') and not nb.get('put_hinted'):
        msg = 'You are at the requested destination with the target; put it in/on the ' + dest + ' now.'
    elif stage == 'go_destination' and dest and not nb.get('put_hinted'):
        msg = 'Carry the target to the requested ' + dest + '; do not substitute a different container type.'
    elif stage == 'find_target' and g(ctx, 'predicates.remaining_steps_low', False):
        msg = 'Search systematically for the requested target type; avoid carrying wrong objects or repeating examine/go loops.'
    if not msg:
        return None
    key = stage + '|' + msg
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    if stage in ('take_target', 'transform', 'put_target'):
        nb[stage + '_hinted'] = True
    return {'message': msg}
